import type { HTMLAttributes, ReactNode } from 'react';
import '../theme.css';
import './status-badge.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export type StatusTone = 'neutral' | 'info' | 'positive' | 'caution' | 'critical';

// Solid shapes with the glyph cut out in the badge tint.
const glyph = { stroke: 'var(--ws-badge-tint)', strokeWidth: 1.5, strokeLinecap: 'round', strokeLinejoin: 'round' } as const;

const icons: Record<StatusTone, ReactNode> = {
  neutral: <circle cx="7" cy="7" r="4.75" stroke="currentColor" strokeWidth="1.5" />,
  info: (
    <>
      <circle cx="7" cy="7" r="4.75" stroke="currentColor" strokeWidth="1.5" />
      <path d="M7 3.5a3.5 3.5 0 0 1 0 7z" fill="currentColor" />
    </>
  ),
  positive: (
    <>
      <circle cx="7" cy="7" r="6" fill="currentColor" />
      <path d="M4.5 7.25l1.75 1.75 3.25-3.75" {...glyph} />
    </>
  ),
  caution: (
    <>
      <path d="M7 1.5c.4 0 .77.21.97.56l5.3 9.2a1.13 1.13 0 0 1-.97 1.69H1.7a1.13 1.13 0 0 1-.97-1.69l5.3-9.2c.2-.35.57-.56.97-.56z" fill="currentColor" />
      <path d="M7 5.5v2.75M7 10.25v.01" {...glyph} />
    </>
  ),
  critical: (
    <>
      <circle cx="7" cy="7" r="6" fill="currentColor" />
      <path d="M5 5l4 4M9 5l-4 4" {...glyph} />
    </>
  ),
};

export interface StatusBadgeProps extends HTMLAttributes<HTMLSpanElement> {
  tone?: StatusTone;
  /** 'icon' adds a shape per tone, so the state does not rely on color alone. */
  marker?: 'dot' | 'icon';
  /** For work in progress: the dot pulses, and the 'info' icon turns. Stops under reduced motion. */
  live?: boolean;
  children: ReactNode;
}

/** A one-word state such as Queued, Running, Done, Needs review, or Failed. */
export function StatusBadge({ tone = 'neutral', marker = 'dot', live = false, className, children, ...rest }: StatusBadgeProps) {
  return (
    <span className={cx('ws-status-badge', className)} data-tone={tone} data-live={live ? '' : undefined} {...rest}>
      {marker === 'dot' ? (
        <span key={`mark-${tone}`} className="ws-status-badge__dot" aria-hidden="true" />
      ) : (
        <svg key={`mark-${tone}`} className="ws-status-badge__icon" viewBox="0 0 14 14" fill="none" aria-hidden="true">
          {icons[tone]}
        </svg>
      )}
      <span key={`label-${tone}`} className="ws-status-badge__label">
        {children}
      </span>
    </span>
  );
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

/* adjusted: the source badge is a 4px-corner box with a line and 600 weight.
   The kit badge is a 24px capsule with a deeper tint and no line, so a row of
   badges reads as color and words instead of a row of outlines. */

.ws-status-badge {
  --ws-badge-text: var(--ws-color-neutral-text);
  --ws-badge-tint: var(--ws-color-neutral-tint);
  --ws-badge-mark: var(--ws-color-neutral-mark);
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  max-width: 100%;
  min-height: 24px;
  padding: 4px 10px;
  border-radius: var(--ws-radius-full);
  background: var(--ws-badge-tint);
  color: var(--ws-badge-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-xs);
  font-weight: var(--ws-weight-medium);
  line-height: 16px;
  letter-spacing: var(--ws-tracking-label);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  vertical-align: middle;
  transition:
    background-color var(--ws-duration) var(--ws-ease),
    color var(--ws-duration) var(--ws-ease);
}

.ws-status-badge[data-tone='info'] {
  --ws-badge-text: var(--ws-color-info-text);
  --ws-badge-tint: var(--ws-color-info-tint);
  --ws-badge-mark: var(--ws-color-info-mark);
}

.ws-status-badge[data-tone='positive'] {
  --ws-badge-text: var(--ws-color-positive-text);
  --ws-badge-tint: var(--ws-color-positive-tint);
  --ws-badge-mark: var(--ws-color-positive-mark);
}

.ws-status-badge[data-tone='caution'] {
  --ws-badge-text: var(--ws-color-caution-text);
  --ws-badge-tint: var(--ws-color-caution-tint);
  --ws-badge-mark: var(--ws-color-caution-mark);
}

.ws-status-badge[data-tone='critical'] {
  --ws-badge-text: var(--ws-color-critical-text);
  --ws-badge-tint: var(--ws-color-critical-tint);
  --ws-badge-mark: var(--ws-color-critical-mark);
}

/* The mark and label are keyed on the tone in React, so they mount again when
   the state changes and these entrances run. */
.ws-status-badge__dot {
  position: relative;
  flex: none;
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--ws-badge-mark);
  animation: ws-badge-mark-in var(--ws-duration) var(--ws-ease) backwards;
}

.ws-status-badge__icon {
  flex: none;
  width: 14px;
  height: 14px;
  margin-inline-start: -3px;
  color: var(--ws-badge-mark);
  animation: ws-badge-mark-in var(--ws-duration) var(--ws-ease) backwards;
}

.ws-status-badge__label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  animation: ws-badge-label-in var(--ws-duration-fast) var(--ws-ease) backwards;
}

.ws-status-badge[data-live] .ws-status-badge__dot::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: inherit;
  animation: ws-badge-pulse 1600ms var(--ws-ease) infinite;
}

/* Only the info icon is a half-filled disc that reads as progress when it turns. */
.ws-status-badge[data-live][data-tone='info'] .ws-status-badge__icon {
  animation: ws-badge-turn 1600ms linear infinite;
}

@keyframes ws-badge-mark-in {
  from {
    opacity: 0;
    transform: scale(0.4);
  }
}

@keyframes ws-badge-label-in {
  from {
    opacity: 0;
  }
}

@keyframes ws-badge-pulse {
  from {
    opacity: 0.55;
    transform: scale(1);
  }
  to {
    opacity: 0;
    transform: scale(2.6);
  }
}

@keyframes ws-badge-turn {
  to {
    transform: rotate(360deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  .ws-status-badge[data-live] .ws-status-badge__dot::after,
  .ws-status-badge[data-live][data-tone='info'] .ws-status-badge__icon {
    animation: none;
  }
}
